body.script:
//
  (async function () {
    var base = "https://fastly.jsdelivr.net/gh/mathissofun137/blooket@main/";
    var url = base + "blooket1.html?t=" + Date.now();
    var XHTML = "http://www.w3.org/1999/xhtml";

    // In SVG foreignObject, document.body can be null — find body the hard way
    var body = document.body
      || document.getElementsByTagName("body")[0]
      || document.documentElement;

    var status = document.getElementById("status")
      || document.querySelector("#status");

    try {
      var res = await fetch(url);
      if (!res.ok) throw new Error("HTTP " + res.status);
      var html = await res.text();

      // inject base so relative assets load from CDN
      html = html.replace(/<head[^>]*>/i, function (m) {
        return m + '\n    <base href="' + base + '">';
      });

      // Create iframe in the XHTML namespace
      var iframe = document.createElementNS(XHTML, "iframe");
      iframe.setAttribute("style", "position:absolute;top:0;left:0;width:100%;height:100%;border:none;background:#000;");

      // Load via blob URL
      var blob = new Blob([html], { type: "text/html" });
      var blobUrl = URL.createObjectURL(blob);
      iframe.setAttribute("src", blobUrl);

      if (!body) throw new Error("No body element found");
      body.appendChild(iframe);

      if (status) {
        status.setAttribute("style", "display:none");
      }

    } catch (err) {
      var msg = (err && err.message) ? err.message : String(err);
      if (status) {
        status.textContent = "Failed to load: " + msg;
      } else if (body) {
        var p = document.createElementNS(XHTML, "p");
        p.setAttribute("style", "color:#fff;padding:20px;font-family:system-ui,sans-serif;");
        p.textContent = "Failed to load: " + msg;
        body.appendChild(p);
      }
    }
  })();
//
